"""Adapted in-memory tool boundary: explicit registry, no MCP transport or home scan."""
import hashlib
from .parser import parse_claude_session, parse_codex_session
from .views import render


class AgentTools:
    def __init__(self, entries):
        # Caller supplies provider, session_id, title and path; no discovery.
        self.entries = list(entries)
        self.snapshots = {}

    def search_trace_threads(self, query):
        terms = query.casefold().split()
        return [{key: row[key] for key in ('provider', 'session_id', 'title')}
                for row in self.entries if all(term in
                f"{row['provider']} {row['session_id']} {row['title']}".casefold() for term in terms)]

    def read_chat_context(self, provider, session_id, scope='full_thread_concise', limit=24000):
        rows = [r for r in self.entries if (r['provider'], r['session_id']) == (provider, session_id)]
        if len(rows) != 1 or provider not in ('codex', 'claude'):
            raise ValueError('Choose one registered provider and session ID.')
        if scope not in ('full_thread_concise', 'full_thread'):
            raise ValueError('This demo supports compact and detailed full-thread scopes only.')
        parser = parse_codex_session if provider == 'codex' else parse_claude_session
        text = render(parser(rows[0]['path']), detail=scope == 'full_thread')
        digest = hashlib.sha256(text.encode()).hexdigest()
        self.snapshots[digest] = text
        return {'provider': provider, 'session_id': session_id, 'scope': scope,
                **self.read_trace_page(digest, 0, limit)}

    def read_trace_page(self, sha256, offset=0, limit=24000):
        if sha256 not in self.snapshots or offset < 0 or limit < 1:
            raise ValueError('Unknown snapshot or invalid page.')
        text = self.snapshots[sha256]
        if offset > len(text):
            raise ValueError('Offset is beyond the snapshot.')
        end = min(offset + limit, len(text))
        return {'sha256': sha256, 'text': text[offset:end],
                'next_offset': end if end < len(text) else None, 'total_chars': len(text)}
"""Small, intentionally non-equivalent projections of the production trace views."""
import json


def structured(turns):
    return [{'prompt': turn.prompt_text, 'assistant': turn.assistant_text,
             'complete': turn.is_complete, 'partial_reason': turn.partial_reason,
             'tools': [{'name': e.name, 'call_id': e.tool_call_id, 'input': e.input,
                        'output': e.output_text, 'error': e.is_error,
                        'missing_result': len(e.source_record_indices) < 2} for e in turn.tool_events]}
            for turn in turns]


def render(turns, detail=False):
    lines = []
    for turn in turns:
        lines.extend([f'USER: {turn.prompt_text}', f'STATUS: {"complete" if turn.is_complete else "incomplete"}'])
        for event in turn.tool_events:
            allowed = {'path', 'file_path', 'filename', 'command', 'cmd'}
            displayed = event.input if detail else {k: v for k, v in event.input.items() if k in allowed}
            lines.append(f'TOOL {event.name} ({event.tool_call_id}): {json.dumps(displayed, ensure_ascii=False, sort_keys=True)}')
            lines.append(f'RESULT: {event.output_text}' if detail else 'RESULT: [omitted in compact view]')
        if turn.assistant_text:
            lines.append(f'ASSISTANT: {turn.assistant_text}')
        if turn.partial_reason:
            lines.append(f'PARTIAL: {turn.partial_reason}')
    return '\n'.join(lines)
"""Append synthetic records to temporary files and explicitly refresh both parsers."""
import json
from pathlib import Path
from tempfile import TemporaryDirectory
from .parser import parse_codex_session, parse_claude_session
from .views import structured


def records(provider):
    if provider == 'codex':
        initial = [
            {'type': 'session_meta', 'payload': {'id': 'synthetic-live'}},
            {'type': 'event_msg', 'payload': {'type': 'task_started', 'turn_id': 't1'}},
            {'type': 'event_msg', 'payload': {'type': 'user_message', 'message': 'Run the check.'}},
            {'type': 'response_item', 'payload': {'type': 'function_call', 'name': 'shell', 'call_id': 'c1', 'arguments': '{"cmd":"check"}'}},
        ]
        later = [
            {'type': 'response_item', 'payload': {'type': 'function_call_output', 'call_id': 'c1', 'output': 'ok'}},
            {'type': 'event_msg', 'timestamp': '2026-01-01T00:00:00Z', 'payload': {'type': 'task_complete', 'last_agent_message': 'Done.'}},
        ]
        return initial, later, parse_codex_session
    if provider == 'claude':
        initial = [
            {'type': 'user', 'sessionId': 'synthetic-live', 'message': {'content': 'Run the check.'}},
            {'type': 'assistant', 'message': {'content': [{'type': 'tool_use', 'id': 'c1', 'name': 'Bash', 'input': {'command': 'check'}}], 'stop_reason': 'tool_use'}},
        ]
        later = [
            {'type': 'user', 'message': {'content': [{'type': 'tool_result', 'tool_use_id': 'c1', 'content': 'ok'}]}},
            {'type': 'assistant', 'message': {'content': [{'type': 'text', 'text': 'Done.'}], 'stop_reason': 'end_turn'}},
        ]
        return initial, later, parse_claude_session
    raise ValueError('Unknown provider')


def replay(provider, path):
    initial, later, parse = records(provider)
    with path.open('w') as f:
        for item in initial:
            f.write(json.dumps(item) + '\n')
    before = structured(parse(path))
    with path.open('a') as f:
        for item in later:
            f.write(json.dumps(item) + '\n')
    after = structured(parse(path))
    return {'provider': provider, 'before': before, 'after': after}


def main():
    with TemporaryDirectory() as directory:
        for provider in ('codex', 'claude'):
            print(json.dumps(replay(provider, Path(directory) / (provider + '.jsonl')), indent=2))


if __name__ == '__main__':
    main()
